"recommendation": {"h": "ശുപാർശക്കത്ത്", "s": "ശുപാർശക്കത്ത്", "b": ["((pg:ശ്രീ|ശ്രീമതി)) {person} എനിക്ക് {known} നീണ്ട പരിചയമുള്ള വ്യക്തിയാണ്; {prel} ആണ് ((pg:അദ്ദേഹം|അവർ)). ((pg:അദ്ദേഹത്തെ|അവരെ)) ശുപാർശ ചെയ്യുന്നതിൽ എനിക്ക് അതിയായ സന്തോഷമുണ്ട്.", "((pg:അദ്ദേഹം|അവർ)) {quality} ആണ്. സത്യസന്ധതയും വിശ്വാസ്യതയും ഉത്തരവാദിത്തങ്ങൾ ഏറ്റെടുക്കാനുള്ള സന്നദ്ധതയുമുള്ള ഒരാളായാണ് ഞാൻ ((pg:അദ്ദേഹത്തെ|അവരെ)) എന്നും കണ്ടിട്ടുള്ളത്; മറ്റുള്ളവരുമായി നല്ല രീതിയിൽ ഇടപഴകാനും ((pg:അദ്ദേഹത്തിന്|അവർക്ക്)) കഴിയും.", "{purpose} സംബന്ധിച്ച് ((pg:അദ്ദേഹത്തെ|അവരെ)) ഞാൻ നിസ്സംശയം ശുപാർശ ചെയ്യുന്നു. കൂടുതൽ വിവരങ്ങൾ ആവശ്യമെങ്കിൽ എന്നെ ബന്ധപ്പെടാവുന്നതാണ്."], "sm": {"purpose": "താങ്കളുടെ സർവകലാശാലയിലെ എം.ബി.എ. പ്രവേശനം", "sdesig": "അസോസിയേറ്റ് പ്രൊഫസർ, കൊമേഴ്സ് വിഭാഗം"}},
"authority-letter": {"h": "അധികാരപത്രം (മറ്റൊരാളെ ചുമതലപ്പെടുത്താൻ)", "to": "ബ്രാഞ്ച് മാനേജർ / ചുമതലയുള്ള ഉദ്യോഗസ്ഥൻ", "org": "[ഓഫീസിന്റെ / ബാങ്കിന്റെ പേര്]", "s": "അധികാരപത്രം: ((pg:ശ്രീ|ശ്രീമതി)) {person}", "so": "സ്റ്റേറ്റ് ബാങ്ക് ഓഫ് ഇന്ത്യ, മോഡൽ ടൗൺ ശാഖ", "b": ["{sname} എന്ന ഞാൻ, നേരിട്ട് ഹാജരാകാൻ സാധിക്കാത്തതിനാൽ, [[{d1}-ന് ]]എനിക്കുവേണ്ടി {task}[[ എന്റെ {prel} ആയ]] ((pg:ശ്രീ|ശ്രീമതി)) {person} എന്നയാളെ ഇതിനാൽ അധികാരപ്പെടുത്തുന്നു.", "((pg:അദ്ദേഹത്തിന്റെ|അവരുടെ)) തിരിച്ചറിയൽ രേഖ: {idp}. ഈ ജോലി പൂർത്തിയാക്കാൻ ((pg:അദ്ദേഹത്തെ|അവരെ)) അനുവദിക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു. പരിശോധനയ്ക്കായി ((pg:അദ്ദേഹത്തിന്റെ|അവരുടെ)) ഒപ്പ് താഴെ ചേർക്കുന്നു.", "അധികാരപ്പെടുത്തിയ വ്യക്തിയുടെ ഒപ്പ്: ____________________"], "o": {"id": "എന്റെയും ((pg:അദ്ദേഹത്തിന്റെയും|അവരുടെയും)) തിരിച്ചറിയൽ രേഖകളുടെ സ്വയം സാക്ഷ്യപ്പെടുത്തിയ പകർപ്പുകൾ ഇതോടൊപ്പം ചേർക്കുന്നു."}, "sm": {"prel": "സഹോദരൻ"}},
"char-request": {"h": "സ്വഭാവ സർട്ടിഫിക്കറ്റിനുള്ള അപേക്ഷ (പഞ്ചായത്ത് / വാർഡ് കൗൺസിലർ)", "to": "പഞ്ചായത്ത് പ്രസിഡന്റ് / വാർഡ് കൗൺസിലർ", "org": "[ഗ്രാമപഞ്ചായത്ത് / വാർഡ് നമ്പർ]", "s": "{purpose} ആവശ്യത്തിനായി സ്വഭാവ സർട്ടിഫിക്കറ്റ് ലഭിക്കുന്നതിനുള്ള അപേക്ഷ", "so": "വാർഡ് നമ്പർ 12", "b": ["ഞാൻ ഈ പ്രദേശത്തെ ((സ്ഥിരതാമസക്കാരനാണ്|സ്ഥിരതാമസക്കാരിയാണ്)); {since} മുതൽ താഴെ കൊടുത്തിരിക്കുന്ന വിലാസത്തിൽ താമസിച്ചുവരുന്നു. എന്നെയും എന്റെ കുടുംബത്തെയും അങ്ങേക്ക് നന്നായി അറിയാം.", "{purpose} ആവശ്യത്തിനായി എനിക്ക് ഒരു സ്വഭാവ സർട്ടിഫിക്കറ്റ് ആവശ്യമുണ്ട്. ഞാൻ ഇതുവരെ ഒരു ക്രിമിനൽ കേസിലോ നിയമവിരുദ്ധ പ്രവർത്തനത്തിലോ ഉൾപ്പെട്ടിട്ടില്ല. സർട്ടിഫിക്കറ്റ് എത്രയും വേഗം അനുവദിച്ചു തരണമെന്ന് അപേക്ഷിക്കുന്നു."], "o": {"docs": "എന്റെ ആധാർ കാർഡിന്റെ പകർപ്പും അടുത്തിടെ എടുത്ത ഒരു ഫോട്ടോയും ഇതോടൊപ്പം ചേർക്കുന്നു."}, "sm": {"since": "2010", "purpose": "സർക്കാർ ജോലിക്കുള്ള അപേക്ഷ"}},
"condolence": {"h": "അനുശോചനക്കത്ത്", "to": "{rname}", "org": "", "s": "ഹൃദയംഗമമായ അനുശോചനം", "b": ["[[താങ്കളുടെ പ്രിയപ്പെട്ട {drel} ]]{deceased} അന്തരിച്ച വിവരം അറിഞ്ഞപ്പോൾ എനിക്ക് അതിയായ ദുഃഖം തോന്നി. എന്റെ ഹൃദയംഗമമായ അനുശോചനം അറിയിക്കുന്നു.", "ആ സ്നേഹവും ദയയും ഞാൻ എന്നും ഓർക്കും. ഇത്തരമൊരു നഷ്ടത്തിന്റെ വേദന വാക്കുകൾ കൊണ്ട് കുറയ്ക്കാനാവില്ല; എങ്കിലും താങ്കളും കുടുംബവും എന്റെ ചിന്തകളിലും പ്രാർത്ഥനകളിലും ഉണ്ടെന്ന് അറിയുക.", "വരും ദിവസങ്ങളിൽ എന്തെങ്കിലും സഹായം ആവശ്യമെങ്കിൽ മടികൂടാതെ എന്നോട് പറയണം."]},
